{{ config(
    materialized='incremental',
    unique_key='order_id',
    incremental_strategy='merge'
) }}

select order_id, customer_id, order_ts, amount, updated_at
from {{ ref('stg_orders') }}
{% if is_incremental() %}
  -- lookback window absorbs late-arriving updates
  where updated_at > (select dateadd('hour', -3, max(updated_at)) from {{ this }})
{% endif %}
